type Node struct {
	id            string
	valueSet      map[int]struct{}  // Set of broadcast values we've seen
	neighbors     map[string][]string
	replyQueue    chan maelstrom.Message
	mu            sync.Mutex
}

func main() {
	node := maelstrom.NewNode()
	defer node.Close()

	n := &Node{
		id:       "",
		valueSet: make(map[int]struct{}),
		neighbors: make(map[string][]string),
		replyQueue: node.Channel[maelstrom.Message](),
	}

	node.Handle(n.init)
	node.Handle(n.broadcast)
	node.Handle(n.read)
	node.Handle(n.topology)
	node.Run(n.handleReply)
}

func (n *Node) init(msg maelstrom.Message, reply func(string)) {
	if err := json.Unmarshal([]byte(msg.Body), &struct{ ID string }{ID: ""}); err != nil {
		reply("error")
		return
	}

	n.id = msg.ID[4:] // Extract node ID from source (format is "src:ID")

	fmt.Fprintf(os.Stderr, "Node %s initialized\n", n.id)

	// Subscribe to replies from all nodes
	for _, nid := range maelstrom.NodeIDs {
		if nid != n.id {
			go func(target string) {
				msgChan := node.Channel[maelstrom.Message]()
				node.Send(target, msgChan).Close()
				for {
					select {
					case <-msgChan.Done():
						return
					case m := <-n.replyQueue:
						if m.Source == target {
							m.Body = fmt.Sprintf(`{"type":"gossip","value":%d}`, n.valueSet)
							node.RPC(target, msgChan, m)
						}
					}
				}
			}(nid)
		}
	}

	reply("")
}

func (n *Node) broadcast(msg maelstrom.Message, reply func(string)) {
	var input struct {
		Type    string `json:"type"`
		Message int    `json:"message"`
	}

	if err := json.Unmarshal([]byte(msg.Body), &input); err != nil {
		log.Printf("Error parsing broadcast: %v", err)
		reply("")
		return
	}

	n.mu.Lock()
	if _, exists := n.valueSet[input.Message]; !exists {
		n.valueSet[input.Message] = struct{}{}
		n.mu.Unlock()

		// Forward to all neighbors (all other nodes in a gossip protocol)
		for _, neighborID := range maelstrom.NodeIDs {
			if neighborID != n.id {
				msg := fmt.Sprintf(`{"type":"gossip","src":"%s","dest":"%s","value":%d}`, 
					n.id, neighborID, input.Message)
				node.RPC(neighborID, node.Channel[maelstrom.Message](), maelstrom.Message{
					ID:    msg,
					Body:  msg,
					Source: n.id,
					Dest:  neighborID,
				})
			}
		}
		n.mu.Unlock()

		reply("")
	} else {
		n.mu.Unlock()
		reply("")
	}
}

func (n *Node) read(msg maelstrom.Message, reply func(string)) {
	var input struct {
		Type string `json:"type"`
	}

	if err := json.Unmarshal([]byte(msg.Body), &input); err != nil {
		log.Printf("Error parsing read: %v", err)
		reply("")
		return
	}

	n.mu.Lock()
	values := make([]int, 0, len(n.valueSet))
	for k := range n.valueSet {
		values = append(values, k)
	}
	n.mu.Unlock()

	responseBody := fmt.Sprintf(`{"type":"read_ok","in_reply_to":%d,"messages":%v}`, msg.ID[5:], values)
	reply(responseBody)
}

func (n *Node) topology(msg maelstrom.Message, reply func(string)) {
	if err := json.Unmarshal([]byte(msg.Body), &struct{ Topology map[string][]string }{}); err != nil {
		log.Printf("Error parsing topology: %v", err)
		reply("")
		return
	}

	for dest, neighbors := range msg.Body[1:] {
		n.neighbors[dest] = make([]string, len(neighbors))
		copy(n.neighbors[dest], neighbors)
	}

	reply("")
}

func (n *Node) handleReply(msg maelstrom.Message) {
	var gossip struct {
		Type   string `json:"type"`
		Value  int    `json:"value,omitempty"`
	}

	if err := json.Unmarshal([]byte(msg.Body), &gossip); err != nil {
		log.Printf("Error parsing gossip: %v", err)
		return
	}

	if gossip.Type == "gossip" && gossip.Value != 0 {
		n.mu.Lock()
		n.valueSet[gossip.Value] = struct{}{}
		n.mu.Unlock()

		// Forward this value to all other nodes if they don't have it
		for _, neighborID := range maelstrom.NodeIDs {
			if neighborID != n.id && neighborID != msg.Source {
				node.RPC(neighborID, node.Channel[maelstrom.Message](), maelstrom.Message{
					ID:    fmt.Sprintf(`{"type":"gossip","src":"%s","dest":"%s","value":%d}`, n.id, neighborID, gossip.Value),
					Body:  `{"type":"gossip","src":"node","dest":"node","value":` + strconv.Itoa(gossip.Value) + `}`,
					Source: n.id,
					Dest: neighborID,
				})
			}
		}
	}
}

