	var body map[string]interface{}
	json.Unmarshal([]byte(msg.Body), &body)

	inReplyTo := 0
	if v, ok := body["in_reply_to"]; ok {
		if s, ok := v.(float64); ok {
			inReplyTo = int(s)
		} else if str, ok := v.(string); ok {
			if num, err := strconv.Atoi(str); err == nil {
